package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*; class VoiceDeliveryTest{@Test void stateChangesDelivery(){var p=new VoiceProfile("en","test",VoiceTemperament.CALM,1f,1f,0.5f);assertTrue(VoiceDelivery.resolve(p,VoiceDeliveryState.TIRED).rate()<1);assertTrue(VoiceDelivery.resolve(p,VoiceDeliveryState.NERVOUS).rate()>1);assertTrue(VoiceDelivery.resolve(p,VoiceDeliveryState.TIMID).volume()<1);}}
